package id.airi.os;
import android.app.Activity;import android.app.ActivityManager;import android.content.Context;import android.content.Intent;import android.graphics.Color;import android.os.Bundle;import android.os.Environment;import android.os.StatFs;import android.provider.Settings;import android.view.Gravity;import android.view.ViewGroup;import android.widget.LinearLayout;import android.widget.TextView;
public class PerformanceCenterActivity extends Activity{
@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(20),dp(28),dp(20),dp(20));r.setBackgroundColor(Color.rgb(247,245,239));r.addView(t("AIRI Performance",28,true));TextView s=t("Status perangkat dan shortcut optimasi aman",13,false);s.setTextColor(Color.DKGRAY);r.addView(s,lp(-1,-2,0,2,0,18));ActivityManager am=(ActivityManager)getSystemService(Context.ACTIVITY_SERVICE);ActivityManager.MemoryInfo mi=new ActivityManager.MemoryInfo();am.getMemoryInfo(mi);long total=mi.totalMem/1048576L,avail=mi.availMem/1048576L;StatFs sf=new StatFs(Environment.getDataDirectory().getPath());long totalS=sf.getTotalBytes()/1073741824L,freeS=sf.getAvailableBytes()/1073741824L;r.addView(card("RAM",avail+" MB tersedia / "+total+" MB"));r.addView(card("Storage",freeS+" GB tersedia / "+totalS+" GB"));addBtn(r,"Battery Saver",Settings.ACTION_BATTERY_SAVER_SETTINGS);addBtn(r,"Storage Manager",Settings.ACTION_INTERNAL_STORAGE_SETTINGS);addBtn(r,"App Management",Settings.ACTION_APPLICATION_SETTINGS);TextView note=t("AIRI tidak memaksa kill process karena Android mengelola proses sendiri. Fokus v3 adalah UI ringan, sedikit dependency, dan shortcut optimasi yang aman.",12,false);note.setTextColor(Color.GRAY);r.addView(note,lp(-1,-2,0,16,0,0));setContentView(r);}
private TextView card(String a,String b){TextView v=t(a+"\n"+b,16,true);v.setPadding(dp(16),dp(14),dp(16),dp(14));android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(Color.WHITE);d.setCornerRadius(dp(20));d.setStroke(dp(1),Color.rgb(226,225,220));v.setBackground(d);return v;}private void addBtn(LinearLayout r,String s,String action){TextView v=t(s,14,true);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(Color.rgb(48,86,117));d.setCornerRadius(dp(24));v.setBackground(d);v.setOnClickListener(x->{try{startActivity(new Intent(action));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});r.addView(v,lp(-1,dp(50),0,10,0,0));}
private TextView t(String s,float z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.rgb(25,29,32));v.setTypeface(android.graphics.Typeface.create("sans",b?1:0));return v;}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int rr,int b){int ww=w==-1?ViewGroup.LayoutParams.MATCH_PARENT:(w==-2?ViewGroup.LayoutParams.WRAP_CONTENT:w),hh=h==-1?ViewGroup.LayoutParams.MATCH_PARENT:(h==-2?ViewGroup.LayoutParams.WRAP_CONTENT:h);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ww,hh);p.setMargins(dp(l),dp(t),dp(rr),dp(b));return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
